// The made-up world's address for an exploration's prototypes, which run
// on other ports of this computer (their start command is told it as
// FACTORY_WORLD_URL):
//
//   GET  /api/kobble/world/<exploration>        {situation, version, signed_in, tables}
//   POST /api/kobble/world/<exploration>        {version, changes: [{table, op, row}]}
//        → the new world; 409 when made on an older version
//   POST /api/kobble/world/<exploration>/reset  → back to the start of its situation
//
// Unlike the factory's buttons, these answer pages on any port of this
// computer (CORS for localhost origins, and no page header), and no other
// web page. Several tabs and devices ask again every few seconds, so they
// share it live.
import { KobbleRefused, worldChangeSchema, WorldRefused, } from "@software-factory/core";
import { z } from "zod";
import { readBody } from "../http.js";
const PATH = /^\/api\/kobble\/world\/(X-\d+)(\/reset)?$/;
const LOCAL_ORIGIN = /^https?:\/\/(localhost|127\.0\.0\.1|\[::1\])(:\d+)?$/;
const STATUS = { stale: 409, missing: 404, refused: 400 };
const changeAsked = z.strictObject({
    version: z.number().int(),
    changes: z.array(worldChangeSchema),
});
export function isWorldRoute(url) {
    return PATH.test(url.pathname);
}
export async function answerWorld(incoming, response, url, worlds) {
    const origin = incoming.headers.origin;
    if (origin !== undefined && !LOCAL_ORIGIN.test(origin)) {
        reply(response, 403, { error: "Only pages on this computer." });
        return;
    }
    const [, id = "", reset] = PATH.exec(url.pathname) ?? [];
    const answer = (status, body) => {
        reply(response, status, body, origin ?? null);
    };
    const asked = `${incoming.method ?? "GET"}${reset ? " reset" : ""}`;
    if (asked === "OPTIONS" || asked === "OPTIONS reset")
        answer(204, null);
    else if (asked === "GET")
        refusedOr(answer, () => worlds.world(id));
    else if (asked === "POST reset")
        refusedOr(answer, () => worlds.reset(id));
    else if (asked === "POST")
        await change(incoming, answer, worlds, id);
    else
        answer(405, { error: "Not that way." });
}
// Changes a prototype made, on the version it saw.
async function change(incoming, answer, worlds, id) {
    const body = await readBody(incoming).catch(() => null);
    const parsed = changeAsked.safeParse(body);
    if (parsed.success)
        refusedOr(answer, () => worlds.change(id, parsed.data.version, parsed.data.changes));
    else
        answer(400, {
            error: "That is not a change to the world: {version, changes: [{table, op, row}]}.",
        });
}
// The world, or why not: 409 with the world now when the change was made on
// an older version, 404 for an exploration or world that is not there, 400
// for any other change the world refuses.
function refusedOr(answer, act) {
    try {
        answer(200, act());
    }
    catch (error) {
        if (error instanceof KobbleRefused)
            answer(404, { error: error.message });
        else if (error instanceof WorldRefused)
            answer(STATUS[error.why], { error: error.message });
        else
            throw error;
    }
}
function reply(response, status, body, origin = null) {
    const cors = origin
        ? {
            "access-control-allow-origin": origin,
            "access-control-allow-methods": "GET, POST, OPTIONS",
            "access-control-allow-headers": "content-type",
            vary: "origin",
        }
        : {};
    response.writeHead(status, {
        "content-type": "application/json",
        "cache-control": "no-store",
        ...cors,
    });
    response.end(body === null ? "" : JSON.stringify(body));
}
